set -u; git fetch --prune origin main >/dev/null; git checkout main >/dev/null; git reset --hard origin/main >/dev/null; test "$(git rev-parse HEAD)" = "a932b4cef4827f7e6a6ddf49b8265fd266b21c67"; JAVA_HOME="$(/usr/libexec/java_home -v 21)"; export JAVA_HOME; PATH="$JAVA_HOME/bin:$PATH"; export PATH; set +e; ./gradlew :core:data:detekt --no-daemon >/tmp/tracker-detekt-console.txt 2>&1; rc=$?; set -e; echo DETEKT_RC=$rc; python3 - <<'PY'
from pathlib import Path
import json, xml.etree.ElementTree as ET
root=Path('core/data/build')
files=[p for p in root.rglob('*') if p.is_file() and ('detekt' in p.name.lower() or p.suffix.lower() in {'.sarif'})]
print('REPORT_FILES', [str(p) for p in files])
found=0
for p in files:
    try:
        if p.suffix.lower()=='.sarif':
            data=json.loads(p.read_text())
            for run in data.get('runs',[]):
                for r in run.get('results',[]):
                    loc=(r.get('locations') or [{}])[0].get('physicalLocation',{})
                    art=loc.get('artifactLocation',{}).get('uri','')
                    line=loc.get('region',{}).get('startLine','')
                    msg=r.get('message',{}).get('text','')
                    print('DETEKT_ISSUE',r.get('ruleId',''),art,line,msg)
                    found+=1
        elif p.suffix.lower()=='.xml':
            tree=ET.parse(p)
            for f in tree.getroot().findall('.//file'):
                for e in f.findall('error'):
                    print('DETEKT_ISSUE',e.get('source',''),f.get('name',''),e.get('line',''),e.get('message',''))
                    found+=1
        elif p.suffix.lower()=='.txt':
            for line in p.read_text(errors='replace').splitlines():
                if line.strip(): print('DETEKT_TEXT',line)
    except Exception as exc:
        print('REPORT_PARSE_ERROR',p,type(exc).__name__,str(exc))
print('ISSUE_COUNT',found)
PY
echo CONSOLE_TAIL; tail -40 /tmp/tracker-detekt-console.txt; exit 0
